(()=>{'use strict';
const C=window.FranklinAssistantCore,B=window.FranklinAssistantR1293Core;if(!C||!B)return;
const VERSION='FR-NAV1.29.4-HF3.10.4',n=C.norm;
const RULES=[
{id:'city-hall',re:/\b(city hall|city offices?|mayor'?s office|city administration)\b/,current:1,routes:['/civic-involvement/'],en:'Franklin City offices are operating from multiple locations while the municipal complex is being rebuilt. I will check the current City source for the specific office, address, phone number or hours you need.',es:'Las oficinas de la Ciudad de Franklin funcionan en varias ubicaciones mientras se reconstruye el complejo municipal. Consultaré la fuente actual de la Ciudad para la oficina, dirección, teléfono u horario que necesite.'},
{id:'permit',re:/\b(permit|permits|fence|deck|remodel|renovation|addition|building project|construction)\b/,routes:['/permits-home/','/help/home/permit-contractor/'],en:'For a Franklin home project, start with the exact address and work you plan to do. Then confirm whether the City requires a permit, zoning review, inspection or contractor documentation before work starts.',es:'Para un proyecto de vivienda en Franklin, empiece con la dirección y el trabajo exactos. Luego confirme si la Ciudad exige permiso, revisión de zonificación, inspección o documentación del contratista antes de comenzar.'},
{id:'school-zone',re:/\b(school zone|zoned school|which school|school enrollment|enroll.*school|kindergarten|attendance zone)\b/,routes:['/school-enrollment/','/address-lookup/'],en:'The correct school and district depend on the exact street address. Use the official address or attendance-zone lookup first, then follow the enrollment checklist for the responsible district.',es:'La escuela y el distrito correctos dependen de la dirección exacta. Use primero la consulta oficial de dirección o zona y luego siga la lista de inscripción del distrito correspondiente.'},
{id:'move-utilities',re:/\b(mov(e|ed|ing)|new to franklin|just moved)\b.{0,80}\b(utility|utilities|water|electric|power|sewer|internet)\b|\b(set up|start|turn on)\b.{0,50}\b(utility|water|electric|power|sewer)\b/,current:1,routes:['/new-to-franklin/'],en:'Utility responsibility can vary by address. Start with the exact service address, then confirm water/sewer, electric and other providers separately before opening accounts or scheduling service.',es:'El proveedor de servicios puede variar según la dirección. Empiece con la dirección exacta y confirme por separado agua/alcantarillado, electricidad y otros proveedores antes de abrir cuentas o programar servicio.'},
{id:'sanitation',re:/\b(trash|garbage|recycling|recycle|brush pickup|bulk pickup|bulk waste|yard waste|sanitation)\b/,current:1,routes:['/everyday-help/'],en:'Trash, recycling, brush and bulk-pickup schedules can change, especially around holidays. I will check current Franklin sanitation information rather than guess at the day or rules.',es:'Los horarios de basura, reciclaje, ramas y recolección voluminosa pueden cambiar, especialmente por feriados. Consultaré la información actual de saneamiento de Franklin en vez de adivinar.'},
{id:'pickleball',re:/\bpickleball\b/,current:1,routes:['/sports/pickleball/','/sports/facilities/'],en:'Franklin has pickleball leagues, clinics and places to play. I will start with the Franklin pickleball guide and verify current registration or facility details when timing matters.',es:'Franklin tiene ligas, clínicas y lugares para jugar pickleball. Empezaré con la guía local y verificaré inscripción o instalaciones actuales cuando la fecha importe.'},
{id:'youth-sports',re:/\b(youth|kid|child|teen)\b.{0,35}\b(soccer|baseball|softball|basketball|football|tennis|golf|volleyball|sports|league)\b|\b(soccer|baseball|softball|basketball|football|tennis|golf|volleyball)\b.{0,35}\b(youth|kid|child|teen)\b/,current:1,routes:['/sports/youth-leagues/','/sports/registration/','/sports/'],en:'For youth sports, the useful answer depends on the sport, age and season. I will start with Franklin youth leagues and current registration, then narrow to the sport you named.',es:'Para deportes juveniles, la respuesta depende del deporte, la edad y la temporada. Empezaré con ligas juveniles e inscripción actual y luego reduciré al deporte indicado.'},
{id:'senior-transport',re:/\b(senior|older adult|elderly|mother|father|parent|caregiver)\b.{0,70}\b(transport|ride|bus|drive|mobility|appointment)\b|\b(transport|ride|bus|mobility)\b.{0,70}\b(senior|older adult|elderly|parent|caregiver)\b/,current:1,routes:['/senior-caregiver/','/local-pathways/transportation-mobility/','/caregiver-coordination-plan/'],en:'For an older adult who cannot drive, separate the trip need first: routine local trips, medical appointments, accessibility needs and whether a caregiver can coordinate. I will check current Franklin-area transportation options and show the most useful planning route.',es:'Para una persona mayor que no puede conducir, separe primero el tipo de viaje: recorridos locales, citas médicas, accesibilidad y apoyo del cuidador. Consultaré opciones actuales del área de Franklin y mostraré la ruta de planificación más útil.'},
{id:'food-benefits',re:/\b(snap|food assistance|food pantry|food bank|groceries|food benefits)\b/,current:1,routes:['/local-pathways/food-benefits/'],en:'If food is needed now, immediate food access and SNAP or benefit eligibility are separate tasks. I will separate them so you can address the urgent need while checking current eligibility and application information.',es:'Si necesita alimentos ahora, el acceso inmediato y la elegibilidad para SNAP u otros beneficios son tareas distintas. Las separaré para atender lo urgente y verificar elegibilidad y solicitud actuales.'},
{id:'job-loss',re:/\b(lost my job|job loss|laid off|layoff|unemployed|unemployment)\b/,current:1,routes:['/life-change-plans/job-loss-coverage-household/','/work-income-plan/','/local-pathways/jobs-career/'],en:'After a job loss, handle income or benefits, health coverage, essential bills and the next job search together. I can organize those into one Franklin follow-through plan instead of treating employment as the only issue.',es:'Después de perder un empleo, conviene manejar juntos ingresos o beneficios, cobertura de salud, gastos esenciales y la búsqueda siguiente. Puedo organizarlos en un solo plan de seguimiento.'},
{id:'vehicle-crash',re:/\b(car|auto|vehicle)\b.{0,25}\b(crash|accident|collision)\b|\b(crash|accident|collision)\b.{0,25}\b(car|auto|vehicle)\b/,routes:['/help/auto/crash-next-steps/','/chronology-evidence/'],en:'After a vehicle crash, address immediate safety first, then preserve basic facts, photos, contact and insurance information, and a timeline while details are fresh. The crash organizer can walk through those steps without deciding fault.',es:'Después de un choque, atienda primero la seguridad inmediata y luego conserve hechos básicos, fotos, datos de contacto y seguro y una cronología. El organizador guía esos pasos sin decidir culpa.'},
{id:'vehicle-recall',re:/\b(recall|safety recall)\b/,current:1,routes:['/help/auto/recall-safety/'],en:'A recall answer should come from the current VIN, manufacturer or federal recall record—not a general repair listing. I will route you to the recall-safety check and current source.',es:'Una respuesta sobre retiros debe venir del VIN, fabricante o registro federal actual, no de una lista general de talleres. Le mostraré la verificación de seguridad y la fuente actual.'},
{id:'used-car',re:/\b(used car|used vehicle|dealer)\b.{0,55}\b(warranty|problem|issue|broke|repair|return)\b|\bwarranty\b.{0,45}\b(used car|used vehicle|dealer)\b/,routes:['/life-change-plans/used-vehicle-purchase-problem/','/help/auto/used-car-warranty/'],en:'For a used-vehicle problem, gather the sales documents, warranty language, repair history, dates and what the seller or dealer represented. Then separate mechanical, warranty, financing and consumer-rights questions before choosing the next contact.',es:'Para un problema con un vehículo usado, reúna documentos de venta, garantía, historial de reparaciones, fechas y lo que indicó el vendedor. Luego separe preguntas mecánicas, de garantía, financiamiento y derechos del consumidor.'},
{id:'health-denial',re:/\b(health|medical|insurance|coverage)\b.{0,55}\b(denied|denial|appeal)\b|\b(denied|denial|appeal)\b.{0,55}\b(health|medical|insurance|coverage)\b/,routes:['/help/health/coverage-appeal/','/appeal-review-prep/'],en:'For a health-coverage denial, identify the exact denial reason, decision date, appeal instructions and any deadline printed on the notice. The organizer can help prepare records and questions; current plan appeal rules control.',es:'Para una denegación de cobertura médica, identifique el motivo exacto, fecha de decisión, instrucciones de apelación y cualquier plazo impreso. El organizador ayuda a preparar registros y preguntas; rigen las reglas actuales del plan.'},
{id:'hospital-discharge',re:/\b(discharge|leaving the hospital|hospital release|post hospital)\b/,routes:['/help/health/discharge-transition/','/help/health/referral-care-team/'],en:'Before or just after hospital discharge, confirm medications, follow-up appointments, warning signs, equipment or home support, and who to call with questions. The discharge organizer turns those into one follow-through list.',es:'Antes o justo después del alta, confirme medicamentos, citas, señales de alerta, equipo o apoyo en casa y a quién llamar. El organizador de alta convierte eso en una sola lista de seguimiento.'},
{id:'court-notice',re:/\b(court paper|court papers|summons|subpoena|government notice|court notice|served papers|served with)\b/,routes:['/help/legal/court-notice-roadmap/','/notice-claim-organizer/','/chronology-evidence/'],en:'Do not ignore a court or government notice. Identify the issuing court or agency, case or reference number, date received, response or hearing date, and the exact action the paper says is required. Franklin Assistant can organize those facts and help find legal-help options, but it does not calculate legal deadlines.',es:'No ignore un aviso judicial o gubernamental. Identifique tribunal o agencia, número de caso o referencia, fecha recibida, fecha de respuesta o audiencia y la acción exigida. Franklin Assistant organiza esos datos y ayuda a encontrar asistencia, pero no calcula plazos jurídicos.'},
{id:'housing-dispute',re:/\b(landlord|tenant|contractor|home repair)\b.{0,55}\b(dispute|problem|claim|damage|deposit)\b|\b(dispute|problem|claim|damage|deposit)\b.{0,55}\b(landlord|tenant|contractor|home repair)\b|\b(housing|contractor|consumer)\b.{0,40}\bdispute\b/,routes:['/help/legal/housing-consumer-dispute/','/help/home/records-disputes-resources/'],en:'For a housing or contractor dispute, preserve the contract or lease, notices, photos, payment records, messages and dates first. Then separate factual repair or property issues from legal-rights questions so each goes to the right source.',es:'Para una disputa de vivienda o contratista, conserve contrato o arrendamiento, avisos, fotos, pagos, mensajes y fechas. Luego separe los hechos de reparación o propiedad de las preguntas sobre derechos legales.'},
{id:'fraud-scam',re:/\b(fraud|scam|scammed|identity theft)\b/,routes:['/life-change-plans/fraud-scam-consumer-recovery/','/chronology-evidence/'],en:'If you may have been scammed, stop additional payment or account access when safe, preserve messages, receipts and account details, and make a short timeline. The recovery plan separates financial-account, identity, reporting and legal follow-up.',es:'Si puede haber sido víctima de una estafa, detenga pagos o acceso adicional cuando sea seguro, conserve mensajes, recibos y datos y haga una cronología breve. El plan separa seguimiento financiero, identidad, reportes y asuntos legales.'},
{id:'business-start',re:/\b(start|open|launch)\b.{0,30}\b(business|company|shop|restaurant)\b|\bnew business\b/,current:1,routes:['/start-a-business/','/local-pathways/start-run-business/'],en:'A practical Franklin business-start sequence is: confirm location and zoning, identify registrations or licenses, check permits that apply, then set up operating and public-facing basics. I will verify current government details where they can change.',es:'Una secuencia práctica es: confirmar ubicación y zonificación, identificar registros o licencias, revisar permisos y luego preparar lo operativo y la presencia pública. Verificaré datos gubernamentales actuales cuando puedan cambiar.'},
{id:'business-growth',re:/\b(grow|market|promote)\b.{0,40}\b(business|customers|company)\b|\bmore local customers\b/,routes:['/local-growth-engine/','/business-dashboard/','/member-growth-workspace/'],en:'Start with one measurable local outcome—calls, appointments, visits, orders or repeat customers. Then check your public profile accuracy and action links and build a focused 30–90 day local growth plan.',es:'Empiece con un resultado local medible—llamadas, citas, visitas, pedidos o clientes recurrentes. Luego revise la exactitud y enlaces de acción del perfil y cree un plan local de 30–90 días.'},
{id:'profile-correction',re:/\b(correct|fix|change|remove|delete|claim|manage)\b.{0,35}\b(profile|listing)\b|\bprofile correction\b/,routes:['/claim-profile/','/corrections/'],en:'Factual profile corrections and removal requests are free. Find the profile first, then use the correction or management path. Community Membership is separate from factual accuracy and ordinary Directory ranking.',es:'Las correcciones y solicitudes de eliminación de perfiles son gratuitas. Encuentre primero el perfil y use la ruta de corrección o gestión. La Membresía es independiente de la exactitud y clasificación ordinaria.'},
{id:'membership-billing',re:/\b(cancel|cancellation|billing|payment method|already paid|renewal|subscription)\b.{0,40}\b(member|membership|subscription)\b|\bmembership\b.{0,30}\b(cancel|billing|payment|renewal)\b/,routes:['/member-account/','/membership-status/','/member-support/'],en:'Use your existing member account to manage the payment method, renewal or cancellation. If a payment may already be processing or completed, check membership status first and do not pay again.',es:'Use su cuenta de miembro para administrar método de pago, renovación o cancelación. Si un pago puede estar procesándose o completado, revise primero el estado y no vuelva a pagar.'},
{id:'membership-info',re:/\b(community membership|membership price|member benefits|join franklin navigator|become a member)\b/,routes:['/membership-start/','/membership-pricing/','/member-value/'],en:'Franklin Navigator Community Membership is optional and currently $35 per year. It adds member tools and profile value; paying does not change factual accuracy or ordinary Directory ranking.',es:'La Membresía Comunitaria de Franklin Navigator es opcional y actualmente cuesta $35 al año. Añade herramientas y valor de perfil; pagar no cambia la exactitud ni la clasificación ordinaria.'},
{id:'events',re:/\b(event|events|festival|things to do|what'?s happening)\b|\b(today|tonight|this weekend|weekend)\b.{0,35}\b(activity|activities|event|events|things to do|concert|festival)\b/,current:1,routes:['/today/','/events/','/activities/'],en:'Event details are time-sensitive. I will check current date, time and source information first, then show the relevant Franklin event or activity page as an optional way to explore more.',es:'Los eventos cambian con el tiempo. Primero verificaré fecha, hora y fuente actuales y luego mostraré la página relevante de Franklin como opción para explorar más.'}
];
function matches(raw){const t=n(raw);return RULES.filter(r=>r.re.test(t))}
function plan(raw,lang='en'){const h=matches(raw),es=lang==='es';if(!h.length)return null;const routes=[],seen=new Set;for(const r of h)for(const p of r.routes||[])if(!seen.has(p)){seen.add(p);routes.push(p)}return{id:h[0].id,title:es?'Respuesta de Franklin Assistant':'Franklin Assistant answer',text:h.slice(0,3).map(r=>r[es?'es':'en']).join(' '),routes:routes.slice(0,6),topics:h.map(r=>r.id),confidence:'high',research:h.some(r=>r.current)}}
function direct(raw,lang='en'){const m=C.mode(raw);if(m==='emergency'||m==='crisis')return B.direct(raw,lang);const p=plan(raw,lang);return p||B.direct(raw,lang)}
function researchNeeded(raw,confidence='low'){const p=plan(raw);if(p)return!!p.research;const t=n(raw);if(/\b(today|tonight|tomorrow|weekend|current|currently|latest|open now|hours|schedule|price|fee|cost|available|availability|weather|closure|closed|deadline|meeting|agenda|election|results|news|registration|register|hoy|esta noche|manana|fin de semana|actual|ultimo|abierto ahora|horario|precio|costo|disponible|clima|cierre|fecha limite|reunion|agenda|eleccion|noticias|inscripcion)\b/.test(t))return true;return B.researchNeeded(raw,confidence)}
function boostRoute(path,raw){const t=n(raw);let s=0;for(const r of matches(raw)){const i=(r.routes||[]).indexOf(path);if(i>=0)s+=120-i*16}if(/\bpickleball\b/.test(t)&&path==='/sports/pickleball/')s+=100;if(/\bsoccer\b/.test(t)&&path==='/sports/soccer/')s+=90;if(/\btennis\b/.test(t)&&path==='/sports/tennis/')s+=90;if(/\bbasketball\b/.test(t)&&path==='/sports/basketball/')s+=90;if(/\bgolf\b/.test(t)&&path==='/sports/golf/')s+=90;if(/\b(running|race)\b/.test(t)&&path==='/sports/running/')s+=90;if(!/\b(member|membership|business|customer|company|grow|marketing|promote)\b/.test(t)&&/\/(member-|membership-|business-|local-growth|growth-desk|navigator-growth-desk)/.test(path))s-=80;return s}
function rerank(hits,raw,limit=5){return(hits||[]).map(x=>({...x,qualityScore:(x.score||0)+boostRoute(x.rec?.p||'',raw)})).sort((a,b)=>b.qualityScore-a.qualityScore||String(a.rec?.p).localeCompare(String(b.rec?.p))).slice(0,limit)}
function preferredRoutes(raw){return plan(raw)?.routes||[]}
function shouldSearchProfiles(raw){if(C.serviceFor(raw))return true;const p=plan(raw);if(p)return false;return C.wantsContact(raw)}
function answerQuality(text,raw){const s=String(text||'').trim();if(s.length<45)return 0;let q=45,t=n(s);for(const w of C.meaningful(raw))if(t.includes(w))q+=6;if(/\b(i can help|tell me which|depends on)\b/i.test(s)&&s.length<170)q-=18;if(/privacy|terms of use|copyright/i.test(s))q-=60;return Math.max(0,Math.min(100,q))}
function cleanRouteHits(h){return B.cleanRouteHits(h)}
window.FranklinAssistantR1294Core=Object.freeze({VERSION,RULES,matches,plan,direct,researchNeeded,boostRoute,rerank,preferredRoutes,shouldSearchProfiles,answerQuality,cleanRouteHits});
})();